  week_end_date date not null,
  week_start_date date not null,
  processed_at timestamp with time zone default now() not null
);

create table if not exists public.world_road_championship_duties (
  id uuid default gen_random_uuid() not null,
  edition_id uuid not null,
  rider_id uuid not null,
  duty_date date not null,
  status text default 'confirmed'::text not null,
  label text default 'World Road Championship Grand Finale'::text not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null
);

create table if not exists public.world_road_championship_editions (
  id uuid default gen_random_uuid() not null,
  season_number integer not null,
  race_date date not null,
  decision_deadline date not null,
  host_country_code text,
  host_country_name_snapshot text,
  climate_week_of_year integer,
  climate_avg_temp_c numeric,
  climate_expected_max_temp_c numeric,
  source_stage_id uuid,
  race_id uuid,
  logo_url text default 'https://okuravitxocyevkexfgi.supabase.co/storage/v1/object/public/Admin%20Staff/Others/world%20championship%20logo.webp'::text not null,
  status text default 'planned'::text not null,
  route_status text default 'pending'::text not null,
  participant_count integer default 0 not null,
  confirmed_count integer default 0 not null,
  champion_rider_id uuid,
  champion_name_snapshot text,
  champion_club_id uuid,
  champion_club_name_snapshot text,
  second_rider_id uuid,
  third_rider_id uuid,
  completed_at timestamp with time zone,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  schedule_draw_status text default 'pending'::text not null,
  schedule_locked_at timestamp with time zone,
  final_confirmation_open_date date,
  final_decision_deadline date
);

create table if not exists public.world_road_championship_entries (
  id uuid default gen_random_uuid() not null,
  edition_id uuid not null,
  rider_id uuid not null,
  country_code text not null,
  source_national_edition_id uuid not null,
  rider_name_snapshot text not null,
  club_id_snapshot uuid,
  club_name_snapshot text,
  participation_decision text default 'pending'::text not null,
  entry_status text default 'invited'::text not null,
  participation_decision_at timestamp with time zone,
  participation_decision_user_id uuid,
  morale_delta integer default 0 not null,
  invited_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  final_participation_decision text default 'not_open'::text not null,
  final_participation_decision_at timestamp with time zone,
  final_participation_decision_user_id uuid,
  final_morale_delta integer default 0 not null,
  final_decision_notified_at timestamp with time zone
);